const TITLES: [View, string][] = [
    ["search", "capystore: search"],
    ["post", "capystore: post"],
    ["edit", "capystore: edit timeline"],
    ["collections", "capystore: collections"],
    ["links", "capystore: share links"],
    ["webp", "capystore: webp"],
    ["upload", "capystore: upload"],
    ["save", "capystore: save"],
    ["terminal", "capystore: box terminal"],
];

export const WIDGETS: Widget[] = TITLES.map(([view, title]) => ({
    view,
    uri: widgetUri(view),
    title,
    get html() {
        return PAGE.split("__DEFAULT_VIEW__").join(view);
    },
}));
